const state={api:null,ready:false,connected:false,user:null,claims:{},machines:{},dayRecords:{},activeMachine:null,activeRecord:null,dayStop:null,machinesStop:null,inboxStop:null,inbox:{},tab:'inspections',activeFurnace:'A',editing:null,recordPdf:null,pdfUrl:null,selectedMachines:new Set(),adminTab:'users',adminUsers:[],usage:null};
