function classify(v,s){if(!s||!num(v))return 'na';const n=Number(v);if(n<Number(s.lsl)||n>Number(s.usl))return 'red';if(n<=Number(s.lwl)||n>=Number(s.uwl))return 'yellow';return 'green'}
const statusText={green:'Dentro da faixa ideal',yellow:'Zona de atenção / limite',red:'Fora do plano de controle',na:'Sem classificação'};
function recordStatus(r){const vals=Object.entries(r.values||{});if(!vals.length)return 'na';const levels=vals.map(([k,v])=>classify(v,r.specsSnapshot?.[k]));return levels.includes('red')?'red':levels.includes('yellow')?'yellow':levels.includes('na')?'na':'green'}
function bandMarkup(s,v){const points=[['LSL',s.lsl,'red'],['LWL',s.lwl,'yellow'],['Objetivo',s.target,'green'],['UWL',s.uwl,'yellow'],['USL',s.usl,'red']];const status=classify(v,s);return `<div class="dimension-block"><div class="dimension-title"><span>${escape(s.name)} <small>· ${escape(s.unit||'mm')} · ${escape(s.type||'')}</small></span>${v===undefined?'':`<span class="measured">${escape(numPT(v))} ${escape(s.unit||'')}</span>`}</div><div class="band">${points.map(([name,val,cl])=>`<div class="band-item b-${cl}"><span class="band-name">${name}</span><span class="band-value">${escape(numPT(val))}</span></div>`).join('')}</div>${v===undefined?'':`<div class="measurement-status ${status}">${escape(statusText[status])}</div>`}</div>`}
