function clearPdf(){if(state.pdfUrl)URL.revokeObjectURL(state.pdfUrl);state.pdfUrl=null;state.recordPdf=null;$('#pdfPreview').removeAttribute('src');$('#pdfEmpty').hidden=false;$('#downloadPdf').disabled=true;$('#printPdf').disabled=true}
async function createReport(){if(!state.ready)return alertMsg('Firebase não conectado.');const machineIds=MACHINE_IDS.filter(id=>state.selectedMachines.has(id)),date=safeDate($('#reportDate').value);if(!machineIds.length)return alertMsg('Selecione ao menos uma máquina.');const button=$('#generateReport');button.disabled=true;button.textContent='Consultando Firebase...';clearPdf();try{const groups=await Promise.all(machineIds.map(async machine=>{const [records,machineData]=await Promise.all([state.api.read(`public/inspections/${machine}/${date}`),state.api.read(`public/machines/${machine}`)]);return {machine,furnace:fornoFor(machine).id,prefix:machineData?.prefix||'',records:Object.entries(records||{}).map(([key,r])=>({key,...r})).sort((a,b)=>String(a.inspectedAt).localeCompare(String(b.inspectedAt)))}}));const blob=await generatePdf(groups,date);state.recordPdf=blob;state.pdfUrl=URL.createObjectURL(blob);$('#pdfPreview').src=state.pdfUrl+'#view=FitH&toolbar=1';$('#pdfEmpty').hidden=true;$('#downloadPdf').disabled=false;$('#printPdf').disabled=false;alertMsg('Relatório gerado com dados reais: '+groups.reduce((n,g)=>n+g.records.length,0)+' inspeção(ões).')}catch(e){alertMsg('Não foi possível obter dados do Firebase: '+e.message)}finally{button.disabled=false;button.textContent='Gerar visualização do PDF'}}
function downloadPdf(){if(!state.recordPdf)return;const a=document.createElement('a');a.href=state.pdfUrl;a.download='WMoldes_Pecas_controladas_'+safeDate($('#reportDate').value)+'.pdf';document.body.append(a);a.click();a.remove()}
function printPdf(){if(!state.recordPdf)return;const frame=$('#pdfPreview');try{frame.contentWindow.focus();frame.contentWindow.print()}catch{window.open(state.pdfUrl,'_blank','noopener');alertMsg('Prévia aberta: use Imprimir (Ctrl+P) na janela do PDF.')}}
