async function onSession(user){state.user=user;state.claims={};state.inboxStop?.();state.inboxStop=null;if(user){try{await refreshClaims();state.inboxStop=state.api.subscribe(`private/messages/${user.uid}`,v=>{state.inbox=v||{};$('#msgCount').hidden=Object.keys(state.inbox).length===0;renderInbox()},()=>{})}catch(e){alertMsg('Falha ao atualizar permissões: '+e.message)}if(user.email?.toLowerCase()===MASTER_ADMIN_EMAIL&&!isAdmin())$('#bootstrap').hidden=false;else $('#bootstrap').hidden=true;}renderSession()}
