function openAdmin(){if(!isAdmin())return;state.adminTab='users';toggle('adminBackdrop',true);renderAdmin()}
async function renderAdmin(){if(!isAdmin())return;$$('[data-admin-tab]').forEach(e=>e.classList.toggle('active',e.dataset.adminTab===state.adminTab));const out=$('#adminContent');out.innerHTML='<div class="empty-box">Consultando dados reais do Firebase...</div>';try{if(state.adminTab==='users'){const data=await callAdmin('listUsers');state.adminUsers=data.users||[];out.innerHTML=`<section class="admin-section"><h3>Cadastrar acesso</h3><form id="createUserForm"><div class="form-row three">${field('Nome','displayName','','text','required maxlength="80"')}${field('E-mail','email','','email','required')}${field('Senha inicial (mín. 8)','password','','password','required minlength="8"')}</div><div class="form-row" style="margin-top:11px"><label class="field">Permissão<select name="role"><option value="writer">Inspetor / lançamentos</option><option value="viewer">Visualizador autenticado</option><option value="admin">Administrador</option></select></label><div style="display:flex;align-items:end"><button class="btn btn-primary" type="submit">＋ Criar usuário no Firebase Auth</button></div></div></form><p class="inline-help" style="margin-top:8px">A senha inicial é definida pelo administrador. Recomende ao novo usuário alterá-la pelo botão “Esqueci minha senha”.</p></section><section><h3>Contas existentes · ${state.adminUsers.length}</h3>${state.adminUsers.map(u=>`<div class="admin-row"><div><strong>${escape(u.name||u.email||u.uid)}</strong><small>${escape(u.email||'Sem e-mail')} · Último login: ${escape(u.lastSignInTime||'Nunca')}<br>UID ${escape(u.uid)}${u.disabled?' · CONTA BLOQUEADA':''}</small></div><div class="action-pack"><select aria-label="Permissão de ${escape(u.email)}" id="role_${u.uid}"><option value="viewer" ${u.role==='viewer'?'selected':''}>Visualizador</option><option value="writer" ${u.role==='writer'?'selected':''}>Inspetor</option><option value="admin" ${u.role==='admin'?'selected':''}>Administrador</option></select><button class="mini-btn" data-save-role="${escape(u.uid)}">Salvar permissão</button><button class="mini-btn" data-msg-user="${escape(u.uid)}">Mensagem</button><button class="mini-btn" data-reset-user="${escape(u.uid)}">Link de senha</button><button class="mini-btn ${u.disabled?'':'remove'}" data-disable-user="${escape(u.uid)}">${u.disabled?'Reativar':'Bloquear'}</button></div></div>`).join('')}</section>`;$('#createUserForm').onsubmit=createUser;$$('[data-save-role]').forEach(b=>b.onclick=()=>changeRole(b.dataset.saveRole));$$('[data-msg-user]').forEach(b=>b.onclick=()=>sendMessageTo(b.dataset.msgUser));$$('[data-reset-user]').forEach(b=>b.onclick=()=>passwordLink(b.dataset.resetUser));$$('[data-disable-user]').forEach(b=>b.onclick=()=>changeDisabled(b.dataset.disableUser))}
else if(state.adminTab==='usage'){const u=await callAdmin('usage');state.usage=u;const quota=1024*1024*1024;const pct=Math.min(100,u.logicalBytes/quota*100),fmt=x=>x>=1024*1024?(x/1024/1024).toFixed(2)+' MB':(x/1024).toFixed(2)+' KB';out.innerHTML=`<div class="admin-stats"><div class="stat-tile"><b>${escape(fmt(u.logicalBytes))}</b><span>Dados lógicos aproximados do espaço WMoldes</span><div class="usage-meter"><div style="width:${pct.toFixed(4)}%"></div></div><small>${pct.toFixed(5)}% de 1 GB de referência; NÃO é armazenamento faturado</small></div><div class="stat-tile"><b>${u.inspections}</b><span>Inspeções gravadas no WMoldes</span></div><div class="stat-tile"><b>${u.machines}</b><span>Máquinas com informações cadastradas</span></div></div><div class="note-box" style="margin-top:18px"><strong>Limites Spark de referência</strong><p>Armazenamento: 1 GB · Downloads: 10 GB/mês · Até 100 conexões simultâneas.</p><p>Downloads, conexões simultâneas e armazenamento faturado NÃO podem ser calculados com confiabilidade a partir de registros. Consulte os indicadores reais na aba Uso do Firebase.</p><p><a href="https://console.firebase.google.com/project/projetoinspecao-41fb8/database" target="_blank" rel="noopener">Abrir painel do Realtime Database ↗</a></p><p>Contagem atualizada do seu namespace: ${escape(new Date(u.measuredAt).toLocaleString('pt-BR'))}</p></div>`}
else{out.innerHTML=`<section class="admin-section"><h3>Enviar comunicado interno</h3><form id="messageForm"><label class="field">Destinatário<select name="toUid" required>${state.adminUsers.length?state.adminUsers.map(u=>`<option value="${escape(u.uid)}">${escape(u.email||u.uid)}</option>`).join(''):'<option value="">Carregando contas...</option>'}</select></label><label class="field" style="margin-top:12px">Assunto<input name="subject" required maxlength="120" placeholder="Assunto"></label><label class="field" style="margin-top:12px">Mensagem<textarea name="body" required maxlength="3000" placeholder="Mensagem ao colaborador"></textarea></label><button class="btn btn-primary" style="margin-top:12px">Enviar mensagem interna</button></form></section><p class="inline-help">A mensagem é gravada no Realtime Database e aparece na caixa de entrada do usuário ao autenticar. Não envia e-mail.</p>`;if(!state.adminUsers.length){const q=await callAdmin('listUsers');state.adminUsers=q.users||[];state.adminTab='messages';return renderAdmin()}$('#messageForm').onsubmit=sendAdminMessage}
}catch(e){out.innerHTML=`<div class="empty-box">${escape(e.message)}<br>Confira a implantação da função administrativa e o acesso da conta.</div>`}}
async function createUser(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));if(!confirm('Criar conta para '+d.email+'?'))return;try{await callAdmin('createUser',d);alertMsg('Conta criada no Firebase Authentication.');renderAdmin()}catch(e){alertMsg(e.message)}}
async function changeRole(uid){const role=$('#role_'+uid).value;if(!confirm(`Alterar permissão para ${role}?`))return;try{await callAdmin('updateRole',{uid,role});alertMsg('Permissão alterada. A conta afetada deve atualizar seu token ou entrar novamente.');renderAdmin()}catch(e){alertMsg(e.message)}}
async function changeDisabled(uid){const u=state.adminUsers.find(u=>u.uid===uid);if(!u||!confirm((u.disabled?'Reativar':'Bloquear')+' esta conta?'))return;try{await callAdmin('setDisabled',{uid,disabled:!u.disabled});alertMsg('Conta atualizada.');renderAdmin()}catch(e){alertMsg(e.message)}}
async function passwordLink(uid){try{const result=await callAdmin('passwordResetLink',{uid});await navigator.clipboard.writeText(result.url);alertMsg('Link de redefinição copiado. Compartilhe apenas com o dono da conta.')}catch(e){alertMsg('Não foi possível copiar o link: '+e.message)}}
function sendMessageTo(uid){state.adminTab='messages';renderAdmin().then(()=>{const select=$('#messageForm select[name="toUid"]');if(select)select.value=uid})}
async function sendAdminMessage(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{await callAdmin('sendMessage',d);e.currentTarget.reset();alertMsg('Mensagem armazenada para o destinatário no Firebase.')}catch(e){alertMsg('Falha ao enviar: '+e.message)}}
function renderInbox(){const msgs=Object.values(state.inbox||{}).sort((a,b)=>String(b.sentAt||'').localeCompare(String(a.sentAt||'')));$('#inboxContent').innerHTML=msgs.length?msgs.map(m=>`<div class="message-card"><strong>${escape(m.subject||'Comunicado')}</strong><small>${escape(timeLabel(m.sentAt))}</small><p>${escape(m.body)}</p><small>Enviado por ${escape(m.senderEmail||'Administrador')}</small></div>`).join(''):'<div class="empty-box">Nenhuma mensagem recebida.</div>'}
